style.css:
body {
  background: url("https://isorepublic.com/wp-content/uploads/2018/11/space-cosmos-1100x733.jpg") no-repeat center center fixed !important;
  background-size: cover !important;
}

body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.6); /* затемнение */
  z-index: -1;
}

body::after {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  box-shadow: 0 0 25px 5px rgba(0, 153, 255, 0.6) inset;
  pointer-events: none;
  z-index: 9999;
}
